for pattern,repl in [(r'Browse [0-9]+ practical HomeCostEngine',f'Browse {len(items)} practical HomeCostEngine'),(r'content="[0-9]+ practical digital field guides',f'content="{len(items)} practical digital field guides'),(r'Explore [0-9]+ planning books',f'Explore {len(items)} planning books'),(r'>[0-9]+ digital books<',f'>{len(items)} digital books<')]:s=re.sub(pattern,repl,s)
